// Produktkarten-Komponente
const ProductCard = React.memo(({ product, onLike, onDislike, likedProducts = [] }) => {
  const imageUrl = useMemo(() => {
    if (!product.image) return '/placeholder-gift.jpg';
    if (typeof product.image === 'string') {
      if (product.image.includes('src=')) {
        const match = product.image.match(/src="([^"]+)"/);
        return match ? match[1] : '/placeholder-gift.jpg';
      }
      if (product.image.startsWith('http')) return product.image;
      return product.image;
    }
    return '/placeholder-gift.jpg';
  }, [product.image]);

  const handleImageError = useCallback((e) => {
    e.currentTarget.src = '/placeholder-gift.jpg';
  }, []);

  const shopButtonText = product.add_to_cart_text || 'Zum Shop';

  return (
    <div className="bg-white rounded-lg shadow-sm overflow-hidden group transform transition-all duration-300 hover:shadow-lg hover:-translate-y-1 flex flex-col">
      <div className="relative aspect-square">
        <a href={product.url} className="block focus:outline-none">
          <img
            src={imageUrl}
            alt={product.name}
            width={400}
            height={400}
            srcSet={`${imageUrl} 400w, ${imageUrl}?w=800 800w`}
            sizes="(max-width: 768px) 100vw, 400px"
            loading="lazy"
            decoding="async"
            className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
            onError={handleImageError}
          />
          <div className="absolute inset-0 bg-gradient-to-t from-gray-900/30 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
        </a>
        {onLike && (
          <button
            className="absolute top-2 right-2 p-1.5 bg-white/90 backdrop-blur-sm rounded-full opacity-0 group-hover:opacity-100 transition-all duration-200 hover:bg-rose-100 focus:outline-none"
            aria-label="Zur Wunschliste hinzufügen"
            onClick={() => onLike(product.id)}
          >
            <Heart
              className={`w-4 h-4 ${likedProducts.includes(product.id) ? 'text-rose-500 fill-rose-500' : 'text-rose-500'}`}
            />
          </button>
        )}
      </div>
      <div className="p-4 flex flex-col flex-grow">
        <h3 className="text-base font-medium mb-2 text-gray-800 line-clamp-2">{product.name}</h3>
        <div className="flex justify-between items-center gap-2 mt-auto">
          <a
            href={product.url}
            className="text-sm text-teal-600 hover:text-teal-700 font-medium transition-colors duration-200 focus:outline-none"
          >
            Details
          </a>
          <a
            rel="nofollow"
            target="_blank"
            onClick={() => window._paq?.push(['trackEvent', 'Conversion', 'Klick zum Shop', 'Teaser'])}
            href={`/redirect.php?product=${product.slug}`}
            className="px-4 py-1.5 bg-teal-600 text-white rounded-full hover:bg-teal-700 transition-all duration-200 focus:outline-none text-sm font-medium"
          >
            {shopButtonText}
          </a>
        </div>
      </div>
    </div>
  );
});

