// Raster-Komponente für Produkte
const ProductGrid = React.memo(
  ({ products, loading, error, onLike, onDislike, likedProducts, loadMore, hasMore, showMore, setShowMore }) => {
    const observer = useRef();
    const lastProductRef = useCallback(
      (node) => {
        if (loading || !hasMore) return;
        if (observer.current) observer.current.disconnect();
        observer.current = new IntersectionObserver(
          (entries) => {
            if (entries[0].isIntersecting) loadMore();
          },
          { rootMargin: '100px' }
        );
        if (node) observer.current.observe(node);
      },
      [loading, hasMore, loadMore]
    );

    if (loading && !products.length) {
      return (
        <div className="flex flex-col items-center py-12">
          <Loader2 className="w-8 h-8 text-teal-500 animate-spin" />
          <span className="mt-3 text-gray-600">Lade Produkte...</span>
        </div>
      );
    }
    if (error) return <Alert>{error}</Alert>;
    if (!products.length)
      return (
        <div className="text-center py-12">
          <Package className="w-12 h-12 text-gray-300 mx-auto mb-3" />
          <p className="text-gray-600">Keine Produkte gefunden</p>
        </div>
      );

    const initialProducts = products.slice(0, 8);

    return (
      <div className="flex flex-col items-center">
        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4 w-full">
          {(showMore ? products : initialProducts).map((p, index) => (
            <div
              key={p.id}
              ref={index === (showMore ? products.length : initialProducts.length) - 1 ? lastProductRef : null}
            >
              <ProductCard product={p} onLike={onLike} onDislike={onDislike} likedProducts={likedProducts} />
            </div>
          ))}
        </div>
        {!showMore && products.length > 8 && setShowMore && (
          <button
            onClick={() => setShowMore(true)}
            className="mt-6 px-6 py-2 bg-teal-600 text-white rounded-full hover:bg-teal-700 transition-all duration-200 focus:outline-none"
          >
            Mehr anzeigen
          </button>
        )}
        {loading && showMore && (
          <div className="py-6">
            <Loader2 className="w-6 h-6 text-teal-500 animate-spin" />
          </div>
        )}
      </div>
    );
  }
);

